/**
 * Model-based test of the commit log and the applier without LMDB. The "store" is a set of quads per revision; the
 * "base" is a copy of that set at a revision; a "generation" is one commit's delta. The test interleaves commits,
 * sealing, applier steps, worker completions, rebuilds, compaction, suspension, corruption reports and readers, and
 * after every step checks the invariants the redesign is built on: the log has no holes, every exact view reads exactly
 * the model at its revision, the applied revision never decreases, rows memory is released after apply, records a live
 * reader needs are never trimmed, reference counts balance, and a blocked writer is released whenever the applier stops
 * consuming.
 */
class AdjacencyApplierModelTest {

	private static final long BACKLOG_MAX_BYTES = 4 * 32L;
	private static final int SUBJECTS = 4;
	private static final int PREDICATES = 2;
	private static final int OBJECTS = 3;

	record Quad(long subject, long predicate, long object) {
	}

	private static final List<Quad> UNIVERSE = universe();

	private static List<Quad> universe() {
		List<Quad> quads = new ArrayList<>();
		for (long s = 1; s <= SUBJECTS; s++) {
			for (long p = 1; p <= PREDICATES; p++) {
				for (long o = 1; o <= OBJECTS; o++) {
					quads.add(new Quad(s, p, o));
				}
			}
		}
		return Collections.unmodifiableList(quads);
	}

	enum Op {
		STAGE,
		CONFIRM,
		RETRACT,
		APPEND_OVERFLOWED,
		SEAL_OK,
		SEAL_FAIL,
		SEAL_OVERFLOWED,
		STEP,
		WORKER,
		TIMER,
		ACQUIRE_HEAD,
		ACQUIRE_APPLIED,
		ACQUIRE_RANDOM,
		RELEASE_VIEW,
		SUSPEND,
		RESUME,
		REBUILD,
		CORRUPTION,
		TOGGLE_FITS,
		FAIL_NEXT_BUILD,
		FAIL_NEXT_PREPARE,
		COMMIT_DURING_SCAN,
		TOGGLE_COMPACTION,
		REQUEST_COMPACTION,
		REQUEST_FOLD,
		SETTLE
	}

	private static final EnumSet<Op> EXHAUSTIVE_OPS = EnumSet.of(Op.STAGE, Op.CONFIRM, Op.SEAL_OK, Op.SEAL_OVERFLOWED,
			Op.STEP, Op.WORKER, Op.ACQUIRE_HEAD, Op.RELEASE_VIEW, Op.REBUILD, Op.FAIL_NEXT_PREPARE);

	@Test
	void randomInterleavingsPreserveEveryInvariant() {
		for (int seed = 0; seed < 1500; seed++) {
			try (Harness harness = new Harness(seed, true)) {
				Random random = new Random(seed * 7919L);
				List<Op> ops = new ArrayList<>(EnumSet.allOf(Op.class));
				for (int i = 0; i < 200; i++) {
					List<Op> enabled = harness.enabled(ops);
					Op op = enabled.get(random.nextInt(enabled.size()));
					harness.run(op);
				}
				harness.settleAndAssertLive();
			}
		}
	}

	@Test
	void exhaustiveShortInterleavingsPreserveEveryInvariant() {
		int[] explored = new int[1];
		List<Op> ops = new ArrayList<>(EXHAUSTIVE_OPS);
		exhaustive(new ArrayList<>(), ops, 7, explored);
		System.out.println("AdjacencyApplierModelTest explored " + explored[0] + " interleavings exhaustively");
		assertTrue(explored[0] > 10_000, "explored " + explored[0] + " interleavings");
	}

	private void exhaustive(List<Op> prefix, List<Op> ops, int depth, int[] explored) {
		// Replay the prefix from scratch for every extension: the harness is cheap and replay keeps every run
		// deterministic without having to clone reference-counted state.
		List<Op> enabled;
		try (Harness harness = new Harness(1, false)) {
			for (Op op : prefix) {
				harness.run(op);
			}
			explored[0]++;
			if (depth == 0) {
				harness.settleAndAssertLive();
				return;
			}
			enabled = harness.enabled(ops);
		}
		for (Op op : enabled) {
			prefix.add(op);
			exhaustive(prefix, ops, depth - 1, explored);
			prefix.remove(prefix.size() - 1);
		}
	}

	@Test
	void unsealedRecordsForceWholesaleFallbackUntilSealed() {
		try (Harness harness = new Harness(3, false)) {
			harness.run(Op.REBUILD);
			harness.settle();
			assertEquals(Status.SERVING, harness.applier.state().status());
			harness.run(Op.STAGE);
			harness.run(Op.CONFIRM);
			long head = harness.log.headRevision();
			try (AdjacencyAcquisition<ModelBase, ModelOverlays> view = harness.applier.acquire(head)) {
				assertFalse(view.exact());
				assertEquals(FallbackReason.PENDING_ROW, view.reason());
			}
			harness.run(Op.SEAL_OK);
			try (AdjacencyAcquisition<ModelBase, ModelOverlays> view = harness.applier.acquire(head)) {
				assertTrue(view.exact(), "sealed pending record serves with a row-level pending set");
				assertEquals(1, view.pending().size());
			}
			harness.settle();
			assertEquals(head, harness.applier.state().appliedRevision());
		}
	}

	@Test
	void overflowedRecordBecomesAGapAndARebuildRetiresIt() {
		try (Harness harness = new Harness(4, false)) {
			harness.run(Op.REBUILD);
			harness.settle();
			harness.run(Op.STAGE);
			harness.run(Op.CONFIRM);
			harness.run(Op.SEAL_OVERFLOWED);
			long gap = harness.log.headRevision();
			harness.scheduler.drain();
			assertEquals(gap, harness.applier.state().gapFromRevision());
			assertEquals(Phase.DEGRADED_GAP, harness.applier.state().phase());
			try (AdjacencyAcquisition<ModelBase, ModelOverlays> view = harness.applier.acquire(gap)) {
				assertEquals(FallbackReason.REVISION_GAP, view.reason());
			}
			try (AdjacencyAcquisition<ModelBase, ModelOverlays> view = harness.applier.acquire(gap - 1)) {
				assertTrue(view.exact(), "readers below the gap keep exact views");
			}
			harness.settle();
			assertEquals(Status.SERVING, harness.applier.state().status());
			assertEquals(gap, harness.applier.state().appliedRevision());
			assertEquals(Long.MAX_VALUE, harness.applier.state().gapFromRevision());
		}
	}

	@Test
	void writersBlockedOnBacklogAreReleasedWhenTheApplierStopsConsuming() {
		try (Harness harness = new Harness(5, false)) {
			harness.run(Op.REBUILD);
			harness.settle();
			for (int i = 0; i < 60 && harness.applier.writeAdmitted(); i++) {
				harness.run(Op.STAGE);
				harness.run(Op.SEAL_OK);
				harness.run(Op.CONFIRM);
			}
			assertFalse(harness.applier.writeAdmitted(), "the backlog bound blocks writers while consuming");
			assertTrue(harness.applier.consuming());
			harness.run(Op.SUSPEND);
			harness.scheduler.drain();
			assertFalse(harness.applier.consuming());
			assertTrue(harness.applier.writeAdmitted(), "a suspended applier admits writers");
			assertEquals(0L, harness.log.unappliedBytes(), "a suspended applier releases its backlog");
			harness.run(Op.RESUME);
			harness.settle();
			assertEquals(harness.log.headRevision(), harness.applier.state().appliedRevision());
		}
	}

	@Test
	void awaitAppliedCompletesOnGapOrUnavailability() throws InterruptedException {
		try (Harness harness = new Harness(6, false)) {
			assertFalse(harness.applier.awaitApplied(1, 0, TimeUnit.MILLISECONDS),
					"nothing serves before the first build");
			harness.run(Op.REBUILD);
			harness.settle();
			harness.run(Op.STAGE);
			harness.run(Op.SEAL_OK);
			harness.run(Op.CONFIRM);
			long head = harness.log.headRevision();
			assertFalse(harness.applier.awaitApplied(head, 0, TimeUnit.MILLISECONDS));
			harness.settle();
			assertTrue(harness.applier.awaitApplied(head, 0, TimeUnit.MILLISECONDS));
			assertTrue(harness.applier.awaitServing(head, 0, TimeUnit.MILLISECONDS));
		}
	}

	// ------------------------------------------------------------------
	// the model
	// ------------------------------------------------------------------

	static final class ModelDelta implements AdjacencyDelta {
		final long revision;
		final List<Quad> quads;
		final List<Boolean> adds;
		final boolean overflowed;
		final Set<Long> pending;
		boolean rowsReleased;

		ModelDelta(long revision, List<Quad> quads, List<Boolean> adds, boolean overflowed) {
			this.revision = revision;
			this.quads = quads;
			this.adds = adds;
			this.overflowed = overflowed;
			Set<Long> touched = new HashSet<>();
			for (Quad quad : quads) {
				touched.add(quad.subject());
			}
			this.pending = overflowed ? null : touched;
		}

		@Override
		public long revision() {
			return revision;
		}

		@Override
		public boolean overflowed() {
			return overflowed;
		}

		@Override
		public boolean empty() {
			return !overflowed && quads.isEmpty();
		}

		@Override
		public long bytes() {
			return overflowed ? 0L : quads.size() * 32L;
		}

		@Override
		public Object pending() {
			return pending;
		}

		@Override
		public void releaseRows() {
			if (rowsReleased) {
				throw new IllegalStateException("rows released twice for revision " + revision);
			}
			rowsReleased = true;
		}
	}

	static class Counted {
		int refs = 1;
		boolean closed;

		void retain() {
			if (refs <= 0) {
				throw new IllegalStateException("retain after release");
			}
			refs++;
		}

		boolean release() {
			if (refs <= 0) {
				throw new IllegalStateException("released more than retained");
			}
			refs--;
			if (refs == 0) {
				closed = true;
				return true;
			}
			return false;
		}
	}

	static final class ModelBase extends Counted {
		final long baseRevision;
		final Set<Quad> rows;

		ModelBase(long baseRevision, Set<Quad> rows) {
			this.baseRevision = baseRevision;
			this.rows = Set.copyOf(rows);
		}
	}

	static final class ModelGeneration extends Counted {
		final long revision;
		final List<Quad> quads;
		final List<Boolean> adds;

		ModelGeneration(long revision, List<Quad> quads, List<Boolean> adds) {
			this.revision = revision;
			this.quads = List.copyOf(quads);
			this.adds = List.copyOf(adds);
		}

		void applyTo(Set<Quad> rows) {
			for (int i = 0; i < quads.size(); i++) {
				if (adds.get(i)) {
					rows.add(quads.get(i));
				} else {
					rows.remove(quads.get(i));
				}
			}
		}
	}

	static final class ModelOverlays extends Counted {
		final List<ModelGeneration> generations;

		ModelOverlays(List<ModelGeneration> generations) {
			this.generations = List.copyOf(generations);
			for (ModelGeneration generation : this.generations) {
				generation.retain();
			}
		}

		void releaseGenerations() {
			for (ModelGeneration generation : generations) {
				generation.release();
			}
		}
	}

	final class ModelOps implements AdjacencyIndexOps<ModelBase, ModelOverlays, ModelGeneration> {
		final Harness harness;
		boolean secondBaseFits = true;
		int failBuilds;
		int failPrepares;
		boolean commitDuringNextScan;
		final List<Counted> allocated = new ArrayList<>();

		ModelOps(Harness harness) {
			this.harness = harness;
		}

		private <T extends Counted> T track(T counted) {
			allocated.add(counted);
			return counted;
		}

		@Override
		public Candidate<ModelBase, ModelOverlays> build(AdjacencyRetentionHold hold) throws Exception {
			if (failBuilds > 0) {
				failBuilds--;
				throw new RuntimeException("injected build failure");
			}
			long pinned = harness.log.headRevision();
			assertTrue(hold.revision() <= pinned, "the hold must not be above the pin");
			hold.narrowTo(pinned);
			if (commitDuringNextScan) {
				commitDuringNextScan = false;
				harness.commitImmediately();
			}
			ModelBase base = track(new ModelBase(pinned, harness.history.get((int) pinned)));
			List<ModelGeneration> generations = new ArrayList<>();
			long applied = pinned;
			for (long revision = pinned + 1; revision <= harness.log.headRevision(); revision++) {
				Record record = harness.log.record(revision);
				assertNotNull(record, "a record above the build hold was trimmed: " + revision);
				if (record.kind() == Kind.OVERFLOWED) {
					releaseAll(base, generations);
					throw new AdjacencyGapException(revision);
				}
				if (!record.sealed()) {
					break;
				}
				if (record.kind() == Kind.DELTA) {
					ModelGeneration generation = prepareFrom(record);
					generations.add(generation);
				}
				applied = revision;
			}
			ModelOverlays overlays = track(new ModelOverlays(generations));
			for (ModelGeneration generation : generations) {
				generation.release(); // the overlays hold the only reference now
			}
			return new Candidate<>(base, overlays, pinned, applied);
		}

		private void releaseAll(ModelBase base, List<ModelGeneration> generations) {
			base.release();
			for (ModelGeneration generation : generations) {
				generation.release();
			}
		}

		private ModelGeneration prepareFrom(Record record) {
			ModelDelta rows = (ModelDelta) record.rows();
			assertNotNull(rows, "rows released before the record was applied: " + record.revision());
			assertFalse(rows.rowsReleased, "rows released before the record was applied: " + record.revision());
			return track(new ModelGeneration(record.revision(), rows.quads, rows.adds));
		}

		@Override
		public ModelGeneration prepare(Record record, ModelBase base, ModelOverlays overlays) {
			if (failPrepares > 0) {
				failPrepares--;
				throw new RuntimeException("injected prepare failure");
			}
			return prepareFrom(record);
		}

		@Override
		public ModelOverlays emptyOverlays(ModelBase base) {
			return track(new ModelOverlays(List.of()));
		}

		@Override
		public ModelOverlays append(ModelOverlays overlays, ModelGeneration generation) {
			List<ModelGeneration> generations = new ArrayList<>(overlays.generations);
			generations.add(generation);
			ModelOverlays appended = track(new ModelOverlays(generations));
			generation.release();
			return appended;
		}

		@Override
		public int generationCount(ModelOverlays overlays) {
			return overlays.generations.size();
		}

		@Override
		public Object generationIdentity(ModelOverlays overlays, int index) {
			return overlays.generations.get(index);
		}

		@Override
		public long generationRevisionAt(ModelOverlays overlays, int index) {
			return overlays.generations.get(index).revision;
		}

		@Override
		public ModelGeneration merge(ModelBase base, ModelOverlays overlays, int from, int toInclusive) {
			List<Quad> quads = new ArrayList<>();
			List<Boolean> adds = new ArrayList<>();
			for (int i = from; i <= toInclusive; i++) {
				ModelGeneration generation = overlays.generations.get(i);
				quads.addAll(generation.quads);
				adds.addAll(generation.adds);
			}
			return track(new ModelGeneration(overlays.generations.get(toInclusive).revision, quads, adds));
		}

		@Override
		public ModelOverlays replaceRange(ModelOverlays overlays, int from, int toInclusive,
				ModelGeneration merged) {
			List<ModelGeneration> generations = new ArrayList<>(overlays.generations.subList(0, from));
			generations.add(merged);
			generations.addAll(overlays.generations.subList(toInclusive + 1, overlays.generations.size()));
			ModelOverlays replaced = track(new ModelOverlays(generations));
			merged.release();
			return replaced;
		}

		@Override
		public Fold<ModelBase> fold(ModelBase base, ModelOverlays overlays, int prefixCount) {
			Set<Quad> rows = new HashSet<>(base.rows);
			long through = base.baseRevision;
			for (int i = 0; i < prefixCount; i++) {
				ModelGeneration generation = overlays.generations.get(i);
				generation.applyTo(rows);
				through = generation.revision;
			}
			return new Fold<>(track(new ModelBase(through, rows)), through);
		}

		@Override
		public ModelOverlays removePrefix(ModelOverlays overlays, int count) {
			return track(new ModelOverlays(overlays.generations.subList(count, overlays.generations.size())));
		}

		@Override
		public void retainBase(ModelBase base) {
			base.retain();
		}

		@Override
		public void retainOverlays(ModelOverlays overlays) {
			overlays.retain();
		}

		@Override
		public boolean secondBaseFits(ModelBase currentBase) {
			return secondBaseFits;
		}

		@Override
		public void releaseBase(ModelBase base) {
			base.release();
		}

		@Override
		public void releaseOverlays(ModelOverlays overlays) {
			if (overlays.release()) {
				overlays.releaseGenerations();
			}
		}

		@Override
		public void releaseGeneration(ModelGeneration generation) {
			generation.release();
		}
	}

	static final class ModelPolicy implements AdjacencyCompactionPolicy<ModelBase, ModelOverlays, ModelGeneration> {
		boolean enabled;

		@Override
		public AdjacencyCompactionPlan select(ModelBase base, ModelOverlays overlays,
				AdjacencyIndexOps<ModelBase, ModelOverlays, ModelGeneration> ops) {
			if (!enabled) {
				return AdjacencyCompactionPlan.none();
			}
			int count = ops.generationCount(overlays);
			if (count >= 6) {
				return AdjacencyCompactionPlan.fold(3);
			}
			if (count >= 4) {
				return AdjacencyCompactionPlan.range(0, 1);
			}
			return AdjacencyCompactionPlan.none();
		}
	}

	// ------------------------------------------------------------------
	// the harness
	// ------------------------------------------------------------------

	final class Harness implements AutoCloseable {
		final Random random;
		final boolean verbose;
		final AdjacencyCommitLog log = new AdjacencyCommitLog(0L);
		final SteppingApplierScheduler scheduler = new SteppingApplierScheduler();
		final DirectWorkerPool workers = new DirectWorkerPool();
		final ModelOps ops = new ModelOps(this);
		final ModelPolicy policy = new ModelPolicy();
		final AdjacencyApplier<ModelBase, ModelOverlays, ModelGeneration> applier;
		/** history.get(r) is the store's content at revision r; revision 0 is the empty store. */
		final List<Set<Quad>> history = new ArrayList<>();
		final List<Op> trace = new ArrayList<>();
		final List<LiveView> views = new ArrayList<>();
		CompletableFuture<ModelDelta> stagedSealing;
		ModelDelta stagedDelta;
		final List<CompletableFuture<ModelDelta>> unsealed = new ArrayList<>();
		final List<ModelDelta> unsealedDeltas = new ArrayList<>();
		long lastApplied = -1;
		boolean suspended;
		boolean writerWasBlocked;

		Harness(long seed, boolean verbose) {
			this.random = new Random(seed);
			this.verbose = verbose;
			history.add(Set.of());
			applier = new AdjacencyApplier<>(log, ops, policy, workers, scheduler, BACKLOG_MAX_BYTES, 1_000L);
			applier.start();
			// post-ready initialisation requests the first build; the test drives when it runs
			applier.requestRebuild();
			checkInvariants();
		}

		record LiveView(AdjacencyAcquisition<ModelBase, ModelOverlays> view, long revision) {
		}

		List<Op> enabled(List<Op> ops) {
			List<Op> result = new ArrayList<>();
			for (Op op : ops) {
				if (isEnabled(op)) {
					result.add(op);
				}
			}
			if (result.isEmpty()) {
				result.add(Op.STEP);
			}
			return result;
		}

		boolean isEnabled(Op op) {
			switch (op) {
			case STAGE:
				return stagedSealing == null && log.headRevision() < 40;
			case CONFIRM:
			case RETRACT:
				return stagedSealing != null;
			case APPEND_OVERFLOWED:
				return stagedSealing == null && log.headRevision() < 40;
			case SEAL_OK:
			case SEAL_FAIL:
			case SEAL_OVERFLOWED:
				return !unsealed.isEmpty();
			case STEP:
				return applier.hasWork();
			case WORKER:
				return workers.hasWork();
			case TIMER:
				return scheduler.hasTimers();
			case ACQUIRE_HEAD:
			case ACQUIRE_APPLIED:
			case ACQUIRE_RANDOM:
				return views.size() < 3 && log.headRevision() > 0;
			case RELEASE_VIEW:
				return !views.isEmpty();
			case SUSPEND:
				return !suspended;
			case RESUME:
				return suspended;
			case COMMIT_DURING_SCAN:
				return !this.ops.commitDuringNextScan && stagedSealing == null;
			default:
				return true;
			}
		}

		void run(Op op) {
			trace.add(op);
			try {
				execute(op);
				checkInvariants();
			} catch (AssertionError | RuntimeException failure) {
				throw new AssertionError("after " + trace + ": " + failure.getMessage(), failure);
			}
		}

		private void execute(Op op) {
			switch (op) {
			case STAGE -> stage();
			case CONFIRM -> confirm();
			case RETRACT -> retract();
			case APPEND_OVERFLOWED -> {
				long revision = log.headRevision() + 1;
				log.appendOverflowed(revision);
				history.add(mutate(history.get(history.size() - 1), random.nextInt(3) + 1));
			}
			case SEAL_OK -> seal(false, false);
			case SEAL_FAIL -> seal(true, false);
			case SEAL_OVERFLOWED -> seal(false, true);
			case STEP -> scheduler.step();
			case WORKER -> workers.runNext();
			case TIMER -> scheduler.fireTimer();
			case ACQUIRE_HEAD -> acquire(log.headRevision());
			case ACQUIRE_APPLIED -> acquire(Math.max(1, Math.min(log.headRevision(),
					applier.state().appliedRevision())));
			case ACQUIRE_RANDOM -> acquire(1 + random.nextInt((int) log.headRevision()));
			case RELEASE_VIEW -> views.remove(random.nextInt(views.size())).view().close();
			case SUSPEND -> {
				suspended = true;
				applier.suspend();
			}
			case RESUME -> {
				suspended = false;
				applier.resume();
			}
			case REBUILD -> applier.requestRebuild();
			case CORRUPTION -> {
				AdjacencyState<ModelBase, ModelOverlays> state = applier.state();
				if (state.status() == Status.SERVING) {
					applier.reportCorruption(state.appliedRevision(), "injected corruption");
				}
			}
			case TOGGLE_FITS -> ops.secondBaseFits = !ops.secondBaseFits;
			case FAIL_NEXT_BUILD -> ops.failBuilds = 1;
			case FAIL_NEXT_PREPARE -> ops.failPrepares = 1;
			case COMMIT_DURING_SCAN -> ops.commitDuringNextScan = true;
			case TOGGLE_COMPACTION -> policy.enabled = !policy.enabled;
			case REQUEST_COMPACTION -> applier.requestCompaction();
			case REQUEST_FOLD -> applier.requestFold();
			case SETTLE -> settle();
			}
		}

		private void stage() {
			long revision = log.headRevision() + 1;
			Set<Quad> before = history.get(history.size() - 1);
			Set<Quad> after = mutate(before, random.nextInt(4));
			List<Quad> quads = new ArrayList<>();
			List<Boolean> adds = new ArrayList<>();
			for (Quad quad : UNIVERSE) {
				boolean was = before.contains(quad);
				boolean is = after.contains(quad);
				if (was != is) {
					quads.add(quad);
					adds.add(is);
				}
			}
			stagedDelta = new ModelDelta(revision, quads, adds, false);
			stagedSealing = new CompletableFuture<>();
			unsealed.add(stagedSealing);
			unsealedDeltas.add(stagedDelta);
			log.stage(revision, stagedSealing);
			// the content is committed only at confirm; remember what it will be
			pendingHistory = after;
		}

		private Set<Quad> pendingHistory;

		/** A commit that lands while a build worker is scanning: stage, seal and confirm in one go. */
		void commitImmediately() {
			stage();
			seal(false, false);
			confirm();
		}

		private void confirm() {
			log.confirm();
			history.add(pendingHistory);
			stagedSealing = null;
			stagedDelta = null;
		}

		private void retract() {
			log.retract();
			int index = unsealed.indexOf(stagedSealing);
			if (index >= 0) {
				unsealed.remove(index);
				unsealedDeltas.remove(index);
			}
			stagedSealing = null;
			stagedDelta = null;
		}

		private void seal(boolean fail, boolean overflowed) {
			int index = unsealed.size() == 1 ? 0 : random.nextInt(unsealed.size());
			CompletableFuture<ModelDelta> sealing = unsealed.remove(index);
			ModelDelta delta = unsealedDeltas.remove(index);
			if (fail) {
				sealing.completeExceptionally(new RuntimeException("injected seal failure"));
			} else if (overflowed) {
				sealing.complete(new ModelDelta(delta.revision, delta.quads, delta.adds, true));
			} else {
				sealing.complete(delta);
			}
		}

		private Set<Quad> mutate(Set<Quad> before, int changes) {
			Set<Quad> after = new HashSet<>(before);
			for (int i = 0; i < changes; i++) {
				Quad quad = UNIVERSE.get(random.nextInt(UNIVERSE.size()));
				if (!after.remove(quad)) {
					after.add(quad);
				}
			}
			return after;
		}

		private void acquire(long revision) {
			AdjacencyAcquisition<ModelBase, ModelOverlays> view = applier.acquire(revision);
			if (view.exact()) {
				checkView(view, revision, true);
				views.add(new LiveView(view, revision));
			} else {
				assertNotNull(view.reason());
				view.close();
			}
		}

		void settle() {
			for (int round = 0; round < 10_000; round++) {
				boolean progressed = scheduler.drain() > 0;
				progressed |= workers.runNext();
				if (!progressed && scheduler.hasTimers()) {
					progressed = scheduler.fireTimer();
				}
				if (!progressed) {
					checkInvariants();
					return;
				}
			}
			fail("the applier never settled after " + trace);
		}

		void settleAndAssertLive() {
			settle();
			boolean unsealedRecords = !unsealed.isEmpty();
			boolean blockedOnViews = !ops.secondBaseFits && !views.isEmpty();
			if (suspended || unsealedRecords || blockedOnViews || stagedSealing != null) {
				return;
			}
			AdjacencyState<ModelBase, ModelOverlays> state = applier.state();
			assertEquals(Status.SERVING, state.status(), "after settling the applier serves: " + state);
			assertEquals(log.headRevision(), state.appliedRevision(), "after settling every record is applied");
			assertEquals(Long.MAX_VALUE, state.gapFromRevision(), "after settling no gap remains");
			try {
				assertTrue(applier.awaitApplied(log.headRevision(), 0, TimeUnit.MILLISECONDS));
				assertTrue(applier.awaitServing(log.headRevision(), 0, TimeUnit.MILLISECONDS));
			} catch (InterruptedException e) {
				throw new AssertionError(e);
			}
			assertTrue(applier.writeAdmitted(), "nothing is unapplied after settling");
		}

		/**
		 * An exact view must read the model at its revision for every row its pending set does not exclude. The seal
		 * and gap checks on the spanned records hold at acquisition; a record may become a gap afterwards (a failed
		 * prepare, a corruption report) without invalidating a view whose pending set already covers its rows.
		 */
		void checkView(AdjacencyAcquisition<ModelBase, ModelOverlays> view, long revision, boolean atAcquisition) {
			AdjacencyState<ModelBase, ModelOverlays> state = view.state();
			assertEquals(Status.SERVING, state.status());
			assertTrue(revision >= state.minSnapshotRevision(), "view below the consolidation floor");
			assertTrue(state.gapFromRevision() > revision, "exact view at or above a gap");
			Set<Quad> rows = new HashSet<>(state.base().rows);
			for (ModelGeneration generation : state.overlays().generations) {
				if (generation.revision <= revision) {
					generation.applyTo(rows);
				}
			}
			Set<Long> pendingSubjects = new HashSet<>();
			for (Object pending : view.pending()) {
				@SuppressWarnings("unchecked")
				Set<Long> subjects = (Set<Long>) pending;
				pendingSubjects.addAll(subjects);
			}
			for (long r = state.appliedRevision() + 1; r <= revision; r++) {
				Record record = log.record(r);
				assertNotNull(record, "exact view spans a trimmed record " + r);
				if (atAcquisition) {
					assertTrue(record.sealed(), "exact view spans an unsealed record " + r);
					assertTrue(record.kind() != Kind.OVERFLOWED, "exact view spans a gap " + r);
				}
			}
			Set<Quad> expected = history.get((int) revision);
			for (Quad quad : UNIVERSE) {
				if (pendingSubjects.contains(quad.subject())) {
					continue;
				}
				assertEquals(expected.contains(quad), rows.contains(quad),
						"row " + quad + " at revision " + revision + " (state applied "
								+ state.appliedRevision() + ", base " + state.base().baseRevision + ")");
			}
		}

		void checkInvariants() {
			AdjacencyState<ModelBase, ModelOverlays> state = applier.state();
			// the log is contiguous between floor and head and nothing exists at or below the floor
			assertNull(log.record(log.floorRevision()), "record at the floor was not trimmed");
			long unreleased = 0;
			for (long r = log.floorRevision() + 1; r <= log.headRevision(); r++) {
				Record record = log.record(r);
				assertNotNull(record, "hole in the log at " + r);
				assertEquals(r, record.revision());
				if (record.kind() == Kind.DELTA && record.sealed() && !record.rowsReleased()) {
					unreleased += record.bytes();
				}
			}
			assertEquals(unreleased, log.unappliedBytes(), "unapplied bytes track unreleased rows");
			// applied never decreases
			assertTrue(state.appliedRevision() >= lastApplied, "applied revision went backwards");
			lastApplied = state.appliedRevision();
			assertTrue(state.appliedRevision() <= log.headRevision(), "applied beyond the head");
			// rows are released once applied unless a build hold still needs them
			long minHold = applier.lowestRetentionHold();
			for (long r = log.floorRevision() + 1; r <= Math.min(state.appliedRevision(), minHold); r++) {
				Record record = log.record(r);
				if (record.kind() == Kind.DELTA && record.sealed()) {
					assertTrue(record.rowsReleased(), "applied rows retained without a hold at " + r);
				}
			}
			// the floor never passes a live state's applied revision or a hold
			assertTrue(log.floorRevision() <= applier.retentionFloor(), "trimmed above the retention floor");
			for (LiveView live : views) {
				AdjacencyState<ModelBase, ModelOverlays> viewState = live.view().state();
				assertTrue(log.floorRevision() <= viewState.appliedRevision(),
						"trimmed records a live view may need");
				checkView(live.view(), live.revision(), false);
			}
			// write admission: released whenever the applier is not consuming or the backlog is small
			if (!applier.consuming() || log.unappliedBytes() < BACKLOG_MAX_BYTES) {
				assertTrue(applier.writeAdmitted(), "writer not admitted while applier not consuming / backlog small");
			} else {
				writerWasBlocked = true;
			}
			if (!applier.consuming() && !applier.hasWork()) {
				assertEquals(0L, log.unappliedBytes(), "a non-consuming applier retains backlog rows");
			}
			// reference counts never go negative and the published state is live
			assertTrue(state.referenceCount() >= 1, "published state fully released");
			for (Counted counted : ops.allocated) {
				assertTrue(counted.refs >= 0);
			}
			if (state.status() == Status.SERVING) {
				assertNotNull(state.base());
				assertNotNull(state.overlays());
				assertTrue(state.base().refs > 0, "serving state holds a released base");
				assertTrue(state.overlays().refs > 0, "serving state holds released overlays");
			}
		}

		@Override
		public void close() {
			for (LiveView live : views) {
				live.view().close();
			}
			views.clear();
			applier.requestClose();
			scheduler.drain();
			workers.runAll();
			scheduler.drain();
			assertEquals(Status.CLOSED, applier.state().status(), "applier closed after draining");
			for (Counted counted : ops.allocated) {
				assertEquals(0, counted.refs, "leaked reference after close: " + counted);
			}
			for (long r = log.floorRevision() + 1; r <= log.headRevision(); r++) {
				Record record = log.record(r);
				if (record != null && record.kind() == Kind.DELTA && record.sealed()) {
					assertTrue(record.rowsReleased(), "rows leaked after close at " + r);
				}
			}
		}
	}
}
